insert into public.landing_testimonials ("id", "name", "quote", "stars", "position", "is_published", "created_at", "updated_at") values
  ('d4478620-5b09-4ab4-8dd9-3cb4e43ea567', 'Elena M.', '{"de":"Ich hätte nie gedacht, dass ich über einen Bildschirm so eine Verbindung lernen könnte.","en":"I never thought I could learn to connect like this with my partner through a screen. Luis and Sara''s methodology is impeccable.","es":"Nunca creí que pudiera aprender a conectar así con mi pareja a través de una pantalla. La metodología de Luis y Sara es impecable.","fr":"Je n''aurais jamais cru pouvoir apprendre à connecter ainsi avec mon partenaire via un écran. La méthodologie de Luis et Sara est impeccable.","it":"La metodologia di Luis e Sara è impeccabile.","ja":"画面越しにこんな風につながることを学べるとは思いませんでした。"}'::jsonb, 5, 1, true, '2026-08-31T11:30:31.518741+00:00', '2026-08-31T11:30:31.518741+00:00'),
  ('4c589932-a874-4ac1-8b02-45fca1e4b7cd', 'Carlos R.', '{"de":"Ich tanze seit Jahren Bachata, aber Bachatango war eine Entdeckung.","en":"I''ve been dancing bachata for years, but bachatango has been a discovery. The elegance they transmit in every class is inspiring.","es":"Llevo años bailando bachata, pero el bachatango ha sido un descubrimiento. La elegancia que transmiten en cada clase es inspiradora.","fr":"Je danse la bachata depuis des années, mais le bachatango a été une découverte. L''élégance qu''ils transmettent dans chaque cours est inspirante.","it":"Il bachatango è stata una scoperta.","ja":"バチャタンゴは発見でした。"}'::jsonb, 5, 2, true, '2026-08-31T11:30:31.518741+00:00', '2026-08-31T11:30:31.518741+00:00'),
  ('0e30c123-dc57-4217-844c-14bc6aba0455', 'Sofía y Marc', '{"de":"Perfekt für das Üben zu Hause. Die technischen Details machen den Unterschied.","en":"Perfect for home practice. Technical details make the difference. 100% recommended.","es":"Perfecto para practicar en casa. Los detalles técnicos marcan la diferencia. 100% recomendado.","fr":"Parfait pour pratiquer à la maison. Les détails techniques font la différence. 100% recommandé.","it":"Perfetto per praticare a casa.","ja":"自宅練習に最適。"}'::jsonb, 5, 3, true, '2026-08-31T11:30:31.518741+00:00', '2026-08-31T11:30:31.518741+00:00')
insert into public.landing_faq ("id", "question", "answer", "position", "is_published", "created_at", "updated_at") values
  ('1436c7bc-3a38-46b9-8dd9-9600d9cdada7', '{"de":"Brauche ich Vorkenntnisse?","en":"Do I need previous dance experience?","es":"¿Necesito tener experiencia previa en baile?","fr":"Ai-je besoin d''expérience en danse ?","it":"Ho bisogno di esperienza?","ja":"経験は必要ですか？"}'::jsonb, '{"de":"Nein. Der Kurs beginnt bei null und baut Schritt für Schritt auf. Wenn du schon Bachata oder Tango tanzt, hast du einen Vorsprung, aber Voraussetzung ist es nicht — wir setzen nur voraus, dass du lernen willst.","en":"No. The course starts from scratch and builds up step by step. If you already dance bachata or tango you will have a head start, but it is not a requirement — all we assume is that you want to learn.","es":"No hace falta. El curso empieza desde cero y avanza paso a paso. Si ya bailas bachata o tango partirás con ventaja, pero no es un requisito: lo único que damos por hecho es que quieres aprender.","fr":"Non. Le cours part de zéro et progresse pas à pas. Si vous dansez déjà la bachata ou le tango, vous aurez une longueur d''avance, mais ce n''est pas obligatoire : la seule chose que nous supposons, c''est votre envie d''apprendre.","it":"No. Il corso parte da zero e procede passo dopo passo. Se balli già bachata o tango partirai avvantaggiato, ma non è un requisito: l''unica cosa che diamo per scontata è la voglia di imparare.","ja":"必要ありません。コースはゼロから始まり、一歩ずつ進みます。バチャータやタンゴの経験があれば有利ですが、必須ではありません。前提となるのは、学びたいという気持ちだけです。"}'::jsonb, 1, true, '2026-08-31T11:30:31.724988+00:00', '2026-08-31T11:30:31.724988+00:00'),
  ('ba8a985c-b949-412e-a88a-af5466468873', '{"de":"Wie greife ich auf die Kurse zu?","en":"How do I access the courses?","es":"¿Cómo accedo a los cursos?","fr":"Comment accéder aux cours ?","it":"Come accedo ai corsi?","ja":"コースへのアクセス方法は？"}'::jsonb, '{"de":"Sobald du einen Kurs kaufst, hast du sofortigen Zugriff auf den gesamten Kursinhalt über die Plattform. Du kannst die Klassen so oft ansehen, wie du möchtest.","en":"Once you buy a course, you have immediate access to all the course content through the platform. You can watch the classes as many times as you want.","es":"Una vez compras un curso, tienes acceso inmediato a todo el contenido del curso a través de la plataforma. Puedes ver las clases tantas veces como quieras.","fr":"Une fois que vous achetez un cours, vous avez un accès immédiat à tout le contenu du cours sur la plateforme. Vous pouvez voir les cours autant de fois que vous le souhaitez.","it":"Una volta acquistato un corso, hai accesso immediato a tutto il contenuto del corso attraverso la piattaforma. Puoi vedere le lezioni tutte le volte che vuoi.","ja":"コースを購入すると、プラットフォームを通じてコースのすべてのコンテンツにすぐにアクセスできます。レッスンは何度でも視聴できます。"}'::jsonb, 2, true, '2026-08-31T11:30:31.724988+00:00', '2026-08-31T11:30:31.724988+00:00'),
  ('df988c96-16b1-4169-9cfe-556e32b553d7', '{"de":"Geht das auch ohne Tanzpartner?","en":"Does it work if I don''t have a dance partner?","es":"¿Sirve si no tengo pareja de baile?","fr":"Est-ce utile si je n''ai pas de partenaire ?","it":"Serve il partner?","ja":"パートナーがいなくても大丈夫？"}'::jsonb, '{"de":"Absolut. Viele Lektionen konzentrieren sich auf individuelle Technik.","en":"Absolutely. Although Bachatango is a partner dance, many lessons focus on individual technique, musicality, and style that you can practice solo.","es":"Absolutamente. Aunque el Bachatango es un baile de pareja, muchas lecciones se enfocan en técnica individual, musicalidad y estilo que puedes practicar solo/a.","fr":"Absolument. Bien que le Bachatango soit une danse de couple, de nombreuses leçons se concentrent sur la technique individuelle, la musicalité et le style.","it":"No, molte lezioni sono individuali.","ja":"もちろんです。"}'::jsonb, 3, true, '2026-08-31T11:30:31.724988+00:00', '2026-08-31T11:30:31.724988+00:00')
insert into auth.users (
